		case .operationCancel(let content):
			try container.encode(CodingKeys.operationCancel, forKey: .type)
			try container.encode(content, forKey: .content)
		case .operationResume(let content):
			try container.encode(CodingKeys.operationResume, forKey: .type)
			try container.encode(content, forKey: .content)
		case .operationAbandon(let content):
			try container.encode(CodingKeys.operationAbandon, forKey: .type)
			try container.encode(content, forKey: .content)
		case .operationGetStats(let content):
			try container.encode(CodingKeys.operationGetStats, forKey: .type)
			try container.encode(content, forKey: .content)
		case .catalogListProviders(let content):
			try container.encode(CodingKeys.catalogListProviders, forKey: .type)
			try container.encode(content, forKey: .content)
		case .catalogGetProvider(let content):
			try container.encode(CodingKeys.catalogGetProvider, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}

/// The reply to one request. Replies on one connection may arrive out of
/// order; clients match them by `requestId`.
public struct Response: Codable, Sendable, Equatable {
	/// The request this answers.
	public let requestId: String
	/// The reply, tagged like the request's call.
	public let reply: Reply

	public init(requestId: String, reply: Reply) {
		self.requestId = requestId
		self.reply = reply
	}
}

/// Params of `operation.resume`.
public struct ResumeOperationParams: Codable, Sendable, Equatable {
	/// The operation to resume.
	public let operationId: UUID
	/// The revision the client saw; a newer one gets
	/// `resource.revision_mismatch`.
	public let expectedRevision: UInt64?

	public init(operationId: UUID, expectedRevision: UInt64?) {
		self.operationId = operationId
		self.expectedRevision = expectedRevision
	}
}

/// Why the daemon stops. Open: newer daemons may add values.
public enum ShutdownReason: String, Codable, Sendable, Equatable {
	/// SIGTERM or SIGINT.
	case signal
	/// A client asked it to stop.
	case requested
	/// A reason this build does not know. The daemon never sends it.
	case unrecognized
}

/// Content of `daemon.shutting_down`.
public struct ShuttingDown: Codable, Sendable, Equatable {
	/// Why the daemon stops.
	public let reason: ShutdownReason

	public init(reason: ShutdownReason) {
		self.reason = reason
	}
}

/// Params of `events.subscribe`.
public struct SubscribeParams: Codable, Sendable, Equatable {
	/// Replay every event after this cursor, or null for new events only.
	public let since: EventCursor?
	/// Full kinds such as `instance.state_changed` or area prefixes ending
	/// in a dot such as `operation.`; empty means every kind. At most 32.
	public let kinds: [String]?
	/// Only events about this resource.
	public let resource: ResourceRef?

	public init(since: EventCursor?, kinds: [String]?, resource: ResourceRef?) {
		self.since = since
		self.kinds = kinds
		self.resource = resource
	}
}

/// Reply of `events.subscribe`. It always precedes the subscription's first
/// event.
public struct Subscribed: Codable, Sendable, Equatable {
	/// Starts at 1 per connection and is never reused on it.
	public let subscriptionId: UInt32
	/// The newest cursor when the subscription started.
	public let head: EventCursor

	public init(subscriptionId: UInt32, head: EventCursor) {
		self.subscriptionId = subscriptionId
		self.head = head
	}
}

/// Params of `events.unsubscribe`.
public struct UnsubscribeParams: Codable, Sendable, Equatable {
	/// The subscription to end.
	public let subscriptionId: UInt32

	public init(subscriptionId: UInt32) {
		self.subscriptionId = subscriptionId
	}
}

/// Where a new secret value comes from (spec 0011 AC-5): shared by
/// `secret.set` and by the requests that create an instance, bring an
/// environment up, or restore.
/// 
/// A reference is the text form `local:<segment>/<segment>...`; it is not a
/// secret and may appear anywhere.
public enum SecretInput: Codable, Sendable, Equatable {
	/// A value the person typed, pasted, or piped in.
	case value(SecretText)
	/// A new random value the daemon generates.
	case generate
	/// A copy of the value stored under another reference.
	case copyFrom(String)
	/// Use an existing reference without writing a value. Only for a new
	/// resource; `secret.set` refuses it.
	case bind(String)

	enum CodingKeys: String, CodingKey, Codable {
		case value,
			generate,
			copyFrom,
			bind
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .value:
				if let content = try? container.decode(SecretText.self, forKey: .content) {
					self = .value(content)
					return
				}
			case .generate:
				self = .generate
				return
			case .copyFrom:
				if let content = try? container.decode(String.self, forKey: .content) {
					self = .copyFrom(content)
					return
				}
			case .bind:
				if let content = try? container.decode(String.self, forKey: .content) {
					self = .bind(content)
					return
				}
			}
		}
		throw DecodingError.typeMismatch(SecretInput.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for SecretInput"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .value(let content):
			try container.encode(CodingKeys.value, forKey: .type)
			try container.encode(content, forKey: .content)
		case .generate:
			try container.encode(CodingKeys.generate, forKey: .type)
		case .copyFrom(let content):
			try container.encode(CodingKeys.copyFrom, forKey: .type)
			try container.encode(content, forKey: .content)
		case .bind(let content):
			try container.encode(CodingKeys.bind, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}

/// Every frame the daemon sends. Adding a variant is a new major.
public enum ServerFrame: Codable, Sendable, Equatable {
	/// The reply to one request.
	case response(Response)
	/// The error for one request, or for a frame without a readable
	/// request.
	case error(ErrorFrame)
	/// One event for one subscription.
	case event(Event)

	enum CodingKeys: String, CodingKey, Codable {
		case response,
			error,
			event
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .response:
				if let content = try? container.decode(Response.self, forKey: .content) {
					self = .response(content)
					return
				}
			case .error:
				if let content = try? container.decode(ErrorFrame.self, forKey: .content) {
					self = .error(content)
					return
				}
			case .event:
				if let content = try? container.decode(Event.self, forKey: .content) {
					self = .event(content)
					return
				}
			}
		}
		throw DecodingError.typeMismatch(ServerFrame.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for ServerFrame"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .response(let content):
			try container.encode(CodingKeys.response, forKey: .type)
			try container.encode(content, forKey: .content)
		case .error(let content):
			try container.encode(CodingKeys.error, forKey: .type)
			try container.encode(content, forKey: .content)
		case .event(let content):
			try container.encode(CodingKeys.event, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}
